def reconcile_ranges(ranges: List[Tuple[int, int]], exclusions: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    # Проверка корректности входных данных
    for r in ranges + exclusions:
        if not isinstance(r[0], int) or not isinstance(r[1], int):
            raise ValueError("Границы интервала должны быть целыми числами")
        if r[0] >= r[1]:
            raise ValueError("Начало интервала должно быть меньше конца")

    # Объединение пересекающихся и соседних интервалов
    merged_ranges = []
    for start, end in sorted(ranges):
        if merged_ranges and merged_ranges[-1][1] >= start:
            merged_ranges[-1] = (merged_ranges[-1][0], max(merged_ranges[-1][1], end))
        else:
            merged_ranges.append((start, end))

    # Вычитание исключений
    result = []
    for start, end in merged_ranges:
        exclude_start, exclude_end = exclusions[0]
        while exclude_start <= end:
            if start < exclude_start:
                result.append((start, min(end, exclude_start)))
            if end > exclude_end:
                start = max(start, exclude_end)
            else:
                break
            if exclusions:
                exclusions.pop(0)
                if exclusions:
                    exclude_start, exclude_end = exclusions[0]

    return sorted(result)

