from typing import List, Tuple

def reconcile_ranges(ranges: List[Tuple[int, int]], exclusions: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    def normalize(intervals: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        if not all(isinstance(start, int) and isinstance(end, int) and start < end for start, end in intervals):
            raise ValueError("Intervals must have integer boundaries with start < end.")
        intervals.sort()
        merged = []
        for current in intervals:
            if not merged or merged[-1][1] < current[0]:
                merged.append(current)
            else:
                merged[-1] = (merged[-1][0], max(merged[-1][1], current[1]))
        return merged

    def subtract_intervals(main: List[Tuple[int, int]], sub: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        result = []
        i, j = 0, 0
        while i < len(main) and j < len(sub):
            main_start, main_end = main[i]
            sub_start, sub_end = sub[j]
            if main_end <= sub_start:
                result.append(main[i])
                i += 1
            elif main_start >= sub_end:
                j += 1
            else:
                if main_start < sub_start:
                    result.append((main_start, sub_start))
                if main_end > sub_end:
                    main[i] = (sub_end, main_end)
                else:
                    i += 1
                    j += 1
        result.extend(main[i:])
        return result

    normalized_ranges = normalize(ranges)
    normalized_exclusions = normalize(exclusions)
    return subtract_intervals(normalized_ranges, normalized_exclusions)

# Сложность объединения и нормализации интервалов O(n log n) и O(m log m) соответственно,
# где n и m - длины списков ranges и exclusions. Вычитание интервалов работает за O(n + m).
