def reconcile_ranges(
    ranges: list[tuple[int, int]],
    exclusions: list[tuple[int, int]],
) -> list[tuple[int, int]]:
    def validate_and_normalize(
        intervals: list[tuple[int, int]],
    ) -> list[tuple[int, int]]:
        for item in intervals:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Каждый интервал должен быть кортежем из 2 элементов.")
            start, end = item
            if type(start) is not int or type(end) is not int:
                raise ValueError("Границы должны быть типа int (bool недопустим).")
            if start >= end:
                raise ValueError(f"start должен быть строго меньше end: [{start}, {end}).")

        sorted_intervals = sorted(intervals)
        merged: list[tuple[int, int]] = []
        for start, end in sorted_intervals:
            if not merged or merged[-1][1] < start:
                merged.append((start, end))
            else:
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        return merged

    merged_ranges = validate_and_normalize(ranges)
    merged_exclusions = validate_and_normalize(exclusions)

    result: list[tuple[int, int]] = []
    ex_idx = 0
    num_ex = len(merged_exclusions)

    for r_start, r_end in merged_ranges:
        curr_start = r_start
        while ex_idx < num_ex and merged_exclusions[ex_idx][1] <= curr_start:
            ex_idx += 1

        while ex_idx < num_ex and merged_exclusions[ex_idx][0] < r_end:
            ex_start, ex_end = merged_exclusions[ex_idx]
            if ex_start > curr_start:
                result.append((curr_start, ex_start))
            curr_start = max(curr_start, ex_end)
            if curr_start >= r_end:
                break
            if ex_end < r_end:
                ex_idx += 1

        if curr_start < r_end:
            result.append((curr_start, r_end))

    return result
