    ranges: list[tuple[int, int]],
    exclusions: list[tuple[int, int]],
) -> list[tuple[int, int]]:
    def _validate_and_normalize(
        raw_list: list[tuple[int, int]]
    ) -> list[tuple[int, int]]:
        validated = []
        for item in raw_list:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Каждый интервал должен быть кортежем из 2 элементов.")
            start, end = item
            # bool является подклассом int в Python, проверяем строго
            if (
                type(start) is not int
                or type(end) is not int
                or start >= end
            ):
                raise ValueError("Границы должны быть int, и start < end.")
            validated.append((start, end))

        if not validated:
            return []

        validated.sort()
        merged = [validated[0]]
