from typing import List, Tuple

def reconcile_ranges(
    ranges: list[Tuple[int, int]],
    exclusions: list[Tuple[int, int]],
) -> list[Tuple[int, int]]:
    def validate_intervals(intervals: list[Tuple[int, int]]) -> None:
        for i in intervals:
            if not isinstance(i[0], int) or not isinstance(i[1], int):
                raise ValueError("Границы интервалов должны быть целыми числами.")
            if i[0] >= i[1]:
                raise ValueError("Начало интервала должно быть меньше конца.")

    validate_intervals(ranges)
    validate_intervals(exclusions)

    # Копирование для неизменности входных данных и сортировка
    sorted_ranges = sorted(ranges, key=lambda x: (x[0], -x[1]))
    sorted_exclusions = sorted(exclusions, key=lambda x: (x[0], -x[1]))

    # Объединение пересекающихся и соседних диапазонов
    merged_ranges = []
    if not sorted_ranges:
        return []

    current_start, current_end = sorted_ranges[0]
    for i in range(1, len(sorted_ranges)):
        next_start, next_end = sorted_ranges[i]
        # Пересечение или соседство (end <= next_start)
        if next_start < current_end:
            current_end = max(current_end, next_end)
        else:
            merged_ranges.append((current_start, current_end))
            current_start, current_end = next_start, next_end
    merged_ranges.append((current_start, current_end))

    # Нормализация исключений (объединение пересекающихся и соседних)
    normalized_exclusions = []
    if not sorted_exclusions:
        return merged_ranges

    current_start, current_end = sorted_exclusions[0]
    for i in range(1, len(sorted_exclusions)):
        next_start, next_end = sorted_exclusions[i]
        if next_start < current_end:
            current_end = max(current_end, next_end)
        else:
            normalized_exclusions.append((current_start, current_end))
            current_start, current_end = next_start, next_end
    normalized_exclusions.append((current_start, current_end))

    # Вычитание нормализованных исключений из объединенных диапазонов
    result_ranges = []
    for r_start, r_end in merged_ranges:
        for e_start, e_end in normalized_exclusions:
            if not (e_start >= r_start and e_end <= r_end):
                # Если исключение не полностью перекрывает текущий диапазон, разбиваем его
                new_ranges = []
                if r_start < e_start:
                    new_ranges.append((r_start, e_start))
                if r_end > e_end:
                    new_ranges.append((e_end, r_end))
                result_ranges.extend(new_ranges)
            else:
                # Если исключение полностью перекрывает текущий диапазон, пропускаем его
                continue

    # Удаление пустых интервалов и сортировка результата
    result_ranges = [r for r in result_ranges if r[0] < r[1]]
    return sorted(result_ranges)

