                raise ValueError("Границы интервалов должны быть целыми числами.")
            if i[0] >= i[1]:
                raise ValueError("Начало интервала должно быть меньше конца.")

    validate_intervals(ranges)
    validate_intervals(exclusions)

    # Копирование для неизменности входных данных
    sorted_ranges = sorted(ranges, key=lambda x: (x[0], x[1]))
    sorted_exclusions = sorted(exclusions, key=lambda x: (x[0], x[1]))

    def merge_intervals(intervals: list[Tuple[int, int]]) -> list[Tuple[int, int]]:
        if not intervals:
            return []

        merged = [intervals[0]]
        for current in intervals[1:]:
            prev_start, prev_end = merged[-1]
            curr_start, curr_end = current

            # Объединяем, если пересекаются или соседние (prev_end == curr_start)
            if curr_start <= prev_end + 1:
                merged[-1] = (prev_start, max(prev_end, curr_end))
            else:
                merged.append(current)
        return merged

    def subtract_intervals(
        intervals: list[Tuple[int, int]], 
        exclusions: list[Tuple[int, int]]
    ) -> list[Tuple[int, int]]:
        if not intervals or not exclusions:
            return intervals

        result = []
        i, j = 0, 0

        while i < len(intervals) and j < len(exclusions):
            start_r, end_r = intervals[i]
            start_e, end_e = exclusions[j]

            if start_e >= start_r:
                # Если исключение полностью внутри текущего интервала или начинается после него
                if end_e <= end_r:
                    # Исключение полностью внутри: ничего не добавляем в этот шаг (но двигаемся дальше)
                    j += 1
                else:
                    # Исключение выходит за пределы интервала, но пересекается с ним
                    result.append((start_r, end_e))
                    i += 1
                    j += 1
            else:
                # Интервал начинается раньше исключения
                if start_r < end_e:
                    result.append((start_r, min(end_r, end_e)))
                i += 1
                j += 1

        # Добавляем оставшиеся интервалы
        while i < len(intervals):
            result.append(intervals[i])
            i += 1

        return result

    merged_ranges = merge_intervals(sorted_ranges)
    final_ranges = subtract_intervals(merged_ranges, sorted_exclusions)

    # Убираем дубликаты и сортируем (хотя merge уже делает это, на всякий случай)
    unique_ranges = []
    if final_ranges:
        last_end = final_ranges[0][1]
        for r in final_ranges:
            if r[1] > last_end:
                unique_ranges.append(r)
                last_end = r[1]

